```ts angular-elements-15/src/app/button/button.component.ts
import {
  ChangeDetectorRef,
  Component,
  EventEmitter,
  Input,
} from "@angular/core";

const BUTTON_CLASSES = {
  primary: "button-primary",
  secondary: "button-secondary",
  secondaryInverse: "button-secondary-inverse",
  tertiary: "button-tertiary",
  background: "button-background",
  ghost: "button-ghost",
};

const BUTTON_SIZES = {
  small: "button-small",
  puffy: "button-puffy",
  default: "button",
};

@Component({
  selector: "app-button",
  templateUrl: "./button.component.html",
  styleUrls: ["./button.component.css"],
})
export class ButtonComponent {
  @Input() typeButton:
    | "primary"
    | "secondary"
    | "secondaryInverse"
    | "tertiary"
    | "background"
    | "ghost" = "primary";
  @Input() iconName = "";
  @Input() sizeButton: "default" | "small" | "puffy" = "default";
  @Input() class = "";
  @Input() icon = "";
  @Input() id = "";
  @Input() disabled = false;
  @Input() iconPosition: "left" | "right" = "right";
  @Input() width: "fill" | "hug" = "fill";
  @Input("aria-label") ariaLabel = "";
  @Input("aria-describedby") ariaDescribedby = "";

  buttonClick = new EventEmitter<void>();

  setClasses(): string[] {
    return [
      this.class,
      this.setButtonType(),
      this.setSize(),
      this.setDynamicSizeClass(),
      this.setIconPosition(),
    ].filter((className) => className !== "");
  }

  private setButtonType(): string {
    return BUTTON_CLASSES[this.typeButton];
  }

  private setSize(): string {
    return BUTTON_SIZES[this.sizeButton];
  }

  private setDynamicSizeClass(): string {
    return this.width === "fill" ? "" : "button-hug";
  }

  private setIconPosition(): string {
    return this.iconPosition === "left" ? "button-icon-left" : "";
  }

  onClick(): void {
    this.buttonClick.emit();
  }
}
```



El problema que describes parece estar relacionado con el uso de `:host` en tu archivo CSS. El selector `:host` se utiliza para aplicar estilos al elemento anfitrión del componente, pero en tu caso, parece que estás tratando de aplicar estilos a los elementos internos del componente.

Para resolver el problema de que el texto "Prueba" se muestra fuera del botón, debes asegurarte de que los estilos se apliquen correctamente al botón y sus elementos internos. Aquí hay algunas sugerencias para solucionar el problema:

